 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    obj = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not obj:
        return out
    r0, r1 = min(r for r, c in obj), max(r for r, c in obj)
    c0, c1 = min(c for r, c in obj), max(c for r, c in obj)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 2)]

    # Extend the rectangle through rows/columns. A marker beyond one side
    # blocks projection on that side; the opposite side remains filled.
    for r in range(r0, r1 + 1):
        left_blocked = any(rr == r and cc < c0 for rr, cc in markers)
        right_blocked = any(rr == r and cc > c1 for rr, cc in markers)
        if not left_blocked:
            for c in range(c0):
                if grid[r][c] == 0: out[r][c] = 2
        if not right_blocked:
            for c in range(c1 + 1, w):
                if grid[r][c] == 0: out[r][c] = 2
    for c in range(c0, c1 + 1):
        up_blocked = any(cc == c and rr < r0 for rr, cc in markers)
        down_blocked = any(cc == c and rr > r1 for rr, cc in markers)
        if not up_blocked:
            for r in range(r0):
                if grid[r][c] == 0: out[r][c] = 2
        if not down_blocked:
            for r in range(r1 + 1, h):
                if grid[r][c] == 0: out[r][c] = 2
    # Preserve marker color over any projection.
    for r, c in markers:
        out[r][c] = grid[r][c]
    return out

if __name__ == '__main__':
    pass
